    }

def get_user_reservations(self, params: dict[str, Any]) -> dict[str, Any]:
    """List all reservation IDs for a customer."""
    user_id = params.get("user_id", "")
    if user_id not in self.users:
        return {"error": f"User {user_id} not found."}

